parameters.functionScript:
const suit = Inputs.suit || 'major';
const suits = Inputs.suits || [];
const cards = Inputs.cards || [];
const here = suits.find(s => s.id === suit) || suits[0] || {};
Outputs.tabs = suits.map(s => ({ id: s.id, name: s.name, selected: s.id === suit }));
Outputs.list = cards
  .filter(c => c.suit === suit)
  .map(c => ({ id: c.id, src: 'cards/' + c.id + '.svg', sub: c.suit === 'major' ? c.name : c.name.split(' of ')[0] }));
Outputs.about = here.about || '';
